// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Test} from "forge-std/Test.sol";
import {ParameterizedVault} from "src/ParameterizedVault.sol";
import {ImdUSD} from "src/ImdUSD.sol";
import {MockIMD} from "src/MockIMD.sol";
import {MockWorkOracle} from "src/MockWorkOracle.sol";
import {TreasuryFactory} from "src/TreasuryFactory.sol";
import {ISwarmFeed} from "src/interfaces/ISwarmFeed.sol";
import {Parameters} from "src/Parameters.sol";
import {APPROVED_OPERATOR, CHAINLINK_ETH_USD, TREASURY_FACTORY} from "src/DeploymentConfig.sol";

contract ChurnFeed is ISwarmFeed {
    uint256 public constant maxAge = 1 days;
    uint256 public value;

    constructor(uint256 v) {
        value = v;
    }

    function set(uint256 v) external {
        value = v;
    }

    function latestValue() external view returns (uint256, uint64) {
        return (value, uint64(block.timestamp));
    }

    function isStale() external pure returns (bool) {
        return false;
    }
}

contract ChurnMirror is ISwarmFeed {
    ISwarmFeed private immutable p;

    constructor(ISwarmFeed p_) {
        p = p_;
    }

    function latestValue() external view returns (uint256, uint64) {
        return p.latestValue();
    }

    function isStale() external view returns (bool) {
        return p.isStale();
    }

    function maxAge() external view returns (uint256) {
        return p.maxAge();
    }
}

contract ChurnAggregator {
    function decimals() external pure returns (uint8) {
        return 8;
    }

    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}

/// @dev A borrower that repays and re-borrows inside ONE transaction, so the round trip is atomic
/// and nothing leaves the system: the same collateral and the same debt afterwards.
contract Churner {
    ParameterizedVault private immutable vault;

    constructor(ParameterizedVault v) {
        vault = v;
    }

    function open(MockIMD imd, uint256 collateral, uint256 debt) external {
        imd.approve(address(vault), collateral);
        vault.lock(collateral);
        vault.draw(debt);
    }

    /// @dev Wipe everything (principal plus the accrued fee) and draw the same figure back.
    function churnDebt() external {
        uint256 debt = vault.debtOf(address(this));
        vault.wipe(debt);
        vault.draw(debt);
    }
}

/// @notice FINDING: the lagged backing (`laggedNow`) is clamped DOWN at once on any decrease and only
/// warms back up over a day, so a borrower who repays and re-borrows in one transaction converts warm
/// capital into fresh capital at will. Nothing left the system, yet `backingPerUnit()` — the figure
/// every redeemer is paid against — falls, and with work-minted supply outstanding it falls to ZERO,
/// which makes `cash` revert `ZeroAmount` for everyone for up to a day. Repeatable for gas.
/// This test fails on the committed code and passes once a same-position re-add within
/// BACKING_WARMUP restores the lagged figure the decrease clamped (or the clamp is otherwise closed).
contract LagChurnTest is Test {
    address private constant WORKER = address(0xCA);
    address private constant REDEEMER = address(0x4E1);
    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;
    MockWorkOracle private oracle;
    Churner private churner;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ChurnAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        // 1 IMD = 1/2000 ETH and 1 ETH = $2000, so the vault prices IMD at exactly $1 per 1e18 raw.
        ChurnFeed primary = new ChurnFeed(uint256(1 ether) * 1e18 / 2000 ether);
        ChurnFeed health = new ChurnFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new ChurnMirror(primary))
        );
        stable = vault.stablecoin();
        oracle = MockWorkOracle(address(vault.oracle()));
        churner = new Churner(vault);
        vm.startPrank(APPROVED_OPERATOR);
        oracle.grantRights(WORKER, 1_000 ether);
        imd.mint(address(churner), 10_000 ether);
        vm.stopPrank();
        // Minting from work switched on the governed way.
        Parameters params = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        params.proposeWage(0.01 ether);
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
    }

    /// @dev With work-minted imdUSD outstanding, the dominant borrower's atomic wipe-and-redraw drives
    /// the lagged figure to zero: every redemption reverts for a day although the system is fully backed.
    function test_atomicRepayAndRedrawDoesNotChangeBackingOrBlockRedemption() public {
        churner.open(imd, 2_000 ether, 1_000 ether); // 200%, well above mat 170
        vm.warp(block.timestamp + vault.BACKING_WARMUP() + 1); // the debt is warm
        vm.prank(WORKER);
        vault.earn(250 ether); // the ceiling: 1000 x 2500 / 10000
        vm.warp(block.timestamp + vault.BACKING_WARMUP() + 1); // everything warm
        vm.startPrank(WORKER);
        stable.transfer(REDEEMER, 100 ether);
        stable.transfer(address(churner), 10 ether); // for the fee the churner accrued meanwhile
        vm.stopPrank();

        assertEq(vault.backingPerUnit(), 1e18, "fully backed: 2000 of collateral behind 1250 of supply");

        churner.churnDebt(); // one transaction: wipe principal + fee, draw the same figure back

        (uint256 collateral, uint256 debt) = vault.positions(address(churner));
        assertEq(collateral, 2_000 ether, "same collateral");
        assertGe(debt, 1_000 ether, "same principal (plus the fee it just converted)");
        assertGe(vault.backingPerUnit() , 1e18 - 1e15, "an atomic round trip must not move backing below par");

        vm.prank(REDEEMER);
        uint256 out = vault.cash(10 ether, 0, address(churner));
        assertGt(out, 9 ether, "redemption must stay open and pay about par less the fee");
    }
}

