    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; totalSupply += amount; }
    function approve(address spender, uint256 amount) external returns (bool) { allowance[msg.sender][spender] = amount; return true; }
    function transfer(address to, uint256 amount) external returns (bool) { balanceOf[msg.sender] -= amount; balanceOf[to] += amount; return true; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        if (allowance[from][msg.sender] != type(uint256).max) allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount; balanceOf[to] += amount; return true;
    }
    function asset() external pure returns (address) { return address(0x1AD); }
    function convertToAssets(uint256 shares) external pure returns (uint256) { return shares * 795 / 100_000_000; }
}
contract ERFeed is ISwarmFeed {
    uint256 public immutable value;
    uint256 public constant maxAge = 1 days;
    constructor(uint256 v) { value = v; }
    function latestValue() external view returns (uint256, uint64) { return (value, uint64(block.timestamp)); }
    function isStale() external pure returns (bool) { return false; }
}
contract ERAggregator {
    function decimals() external pure returns (uint8) { return 8; }
    function latestRoundData() external view returns (uint80, int256, uint256, uint256, uint80) {
        return (1, 2000e8, block.timestamp, block.timestamp, 1);
    }
}
contract ERAdapter {
    function isController(uint256, address) external pure returns (bool) { return true; }
}
contract ERWork is SwarmWorkOracle {
    constructor(address consumer) SwarmWorkOracle(consumer, 1 days) {}
    function seedRoot(bytes32 root) external { _accept(uint256(root), uint64(block.timestamp)); }
}
contract WageOffResidualTest is Test {
    ParameterizedVault vault;
    ERToken shares;
    ERWork work;
    ImdUSD stable;
    address constant BORROWER = address(0xB0B);
    address constant HOLDER = address(0xCAFE);
    uint256 constant PRICE = 79_500_000_000_000; // $10/IMD * 7.95 IMD/sIMD, per 1e18 raw shares

    function setUp() public {
        vm.warp(1_000_000);
        vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ERAggregator()).code);
        vm.etch(ERC8004_ADAPTER, address(new ERAdapter()).code);
        shares = new ERToken();
        ERFeed primary = new ERFeed(5e15); // IMD = $10
        ERFeed nhi = new ERFeed(0.85e18);
        ERFeed spot = new ERFeed(5e15);
        address predicted = vm.computeCreateAddress(address(this), vm.getNonce(address(this)) + 1);
        work = new ERWork(predicted);
        vault = new ParameterizedVault(address(shares), address(0), address(work), address(primary), address(nhi), address(spot));
        assertEq(address(vault), predicted);
        stable = vault.stablecoin();
        shares.mint(BORROWER, 30_000e24);
        vm.prank(BORROWER);
        shares.approve(address(vault), type(uint256).max);
    }
    function _wage(uint256 amount) private {
        Parameters p = vault.parameters();
        vm.prank(APPROVED_OPERATOR);
        p.proposeWage(amount);
        vm.warp(block.timestamp + 48 hours);
        p.applyPending();
    }
    function _lockDollars(uint256 dollars) private {
        vm.prank(BORROWER);
        vault.lock((dollars * 1e18 + PRICE - 1) / PRICE);
    }
    function test_zeroWageMustNotDisableLagForPreviouslyClaimedRights() public {
        _wage(1e18);
        bytes32 root = keccak256(bytes.concat(keccak256(abi.encode(uint256(1), uint32(250), uint64(250)))));
        work.seedRoot(root);
        work.recordRoot();
        vm.prank(BORROWER);
        work.claim(1, 250, 250, new bytes32[](0), root);
        assertEq(work.mintingRights(BORROWER), 250e18);
        _wage(0);
        assertEq(vault.parameters().wage(), 0);
        _lockDollars(2000e18);
        vm.prank(BORROWER);
        vault.draw(1000e18);
        (uint256 lag,) = vault.laggedNow();
        assertEq(lag, 0);
        // Separate top-level calls are separate transactions (the repository's isolate=true).
        // No time elapses between borrowing, earning, repayment and withdrawal.
        vm.prank(BORROWER);
        (bool earned,) = address(vault).call(abi.encodeCall(vault.earn, (250e18)));
        if (!earned) assertEq(vault.totalEarned(), 0);
        vm.prank(BORROWER);
        vault.wipe(1000e18);
        (uint256 collateral,) = vault.positions(BORROWER);
        vm.prank(BORROWER);
        vault.free(collateral);
        assertEq(vault.totalDebt(), 0);
        assertEq(shares.balanceOf(address(vault)), 0);
        assertEq(vault.reserveValue(), 0);
        emit log_named_uint("unbacked work supply", stable.totalSupply());
        // Either earn must refuse while off, or its ceiling must retain the lag.
        assertEq(stable.totalSupply(), 0, "saved rights minted against zero-second debt after wage was switched off");
    }
}

