/// @dev The shape of the successor the parameters record plans (docs/PARAMETERS-2026-10-05.md, "Minting
/// from work"): rights come from a governed tariff per job type, not from `wage()`. Nothing here is
/// hostile: it answers `vault()`, `mintingRights` and `predecessor` exactly as Parameters requires.
contract TariffOracle is IWorkOracle {
    address public immutable vault;
    address public immutable predecessor;
    mapping(address => uint256) public override mintingRights;

    constructor(address vault_, address predecessor_) {
        vault = vault_;
        predecessor = predecessor_;
    }

    function credit(address account, uint256 amount) external {
        mintingRights[account] += amount;
    }

    function consumeRights(address account, uint256 amount) external override {
        require(msg.sender == vault, "vault only");
        mintingRights[account] -= amount;
    }
}

/// @notice FINDING: `ParameterizedVault._lagApplies()` keys the lagged WORK CEILING on
/// `parameters.wage() != 0`, but `earn` mints against whatever `oracle()` answers, and the governed
/// replacement path (`Parameters.proposeWorkOracle`, applicable only while the wage is zero) installs
/// an oracle whose rights need not come from the wage at all. Minting from work is then ON with the
/// D1 lag OFF, and the adjacent-transaction round trip the launch audit closed (borrow -> earn ->
/// unwind) leaves work-minted imdUSD with nothing behind it. This test fails on the committed code
/// and passes once the lag applies whenever work can be minted (e.g. `_lagApplies` returns true, or
/// also when `parameters.workOracle() != address(0)`).
contract ReplacementOracleLagOffTest is Test {
    address private constant ATTACKER = address(0xBAD);
    MockIMD private imd;
    ParameterizedVault private vault;
    ImdUSD private stable;

    function setUp() public {
        if (TREASURY_FACTORY.code.length == 0) vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new RAggregator()).code);
        vm.warp(1_000_000);
        imd = new MockIMD();
        RFeed primary = new RFeed(uint256(1 ether) * 1e18 / 2000 ether); // $1 per IMD
        RFeed health = new RFeed(0.85 ether);
        vault = new ParameterizedVault(
            address(imd), address(0), address(0), address(primary), address(health), address(new RMirror(primary))
        );
        stable = vault.stablecoin();
        vm.prank(APPROVED_OPERATOR);
        imd.mint(ATTACKER, 2_000 ether);
        vm.prank(ATTACKER);
        imd.approve(address(vault), type(uint256).max);

        // Governance installs the successor the documented way: wage still 0, 48-hour timelock.
        Parameters params = vault.parameters();
        TariffOracle successor = new TariffOracle(address(vault), address(vault.oracle()));
        vm.prank(APPROVED_OPERATOR);
        params.proposeWorkOracle(address(successor));
        vm.warp(block.timestamp + params.TIMELOCK());
        params.applyPending();
        assertEq(address(vault.oracle()), address(successor));
        assertEq(params.wage(), 0, "the wage never moved");
        successor.credit(ATTACKER, 1_000 ether);
    }

    /// @dev Each top-level call is its own transaction (foundry.toml isolate), so transient storage
    /// clears between them, exactly as on chain.
    function test_workMintedSupplyNeverOutlivesTheDebtThatAuthorisedIt() public {
        vm.startPrank(ATTACKER);
        vault.lock(2_000 ether);
        vault.draw(1_000 ether);
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);
        // One block later. With the lag in force the ceiling credits about 0.014% of the new debt
        // (about 0.14 imdUSD); without it the whole 1,000 counts and 250 imdUSD of work is mintable.
        uint256 ceiling = vault.earnLine();
        assertLe(ceiling, 1 ether, "a block-old debt must not authorise a quarter of itself in work");
        vault.earn(ceiling == 0 ? 1 : ceiling);
        vm.roll(block.number + 1);
        vm.warp(block.timestamp + 12);
        vault.wipe(vault.debtOf(ATTACKER));
        vault.free(2_000 ether);
        vm.stopPrank();
        assertEq(vault.totalDebt(), 0);
        assertEq(imd.balanceOf(address(vault)), 0, "no collateral left");
        assertLe(stable.totalSupply(), 1 ether, "work-minted supply with nothing behind it");
    }
}

