contract WageOffResidualTest is Test {
    ParameterizedVault vault;
    ERToken shares;
    ERWork work;
    ImdUSD stable;
    address constant BORROWER = address(0xB0B);
    address constant HOLDER = address(0xCAFE);
    uint256 constant PRICE = 79_500_000_000_000; // $10/IMD * 7.95 IMD/sIMD, per 1e18 raw shares

    function setUp() public {
        vm.warp(1_000_000);
        vm.etch(TREASURY_FACTORY, address(new TreasuryFactory()).code);
        vm.etch(CHAINLINK_ETH_USD, address(new ERAggregator()).code);
        vm.etch(ERC8004_ADAPTER, address(new ERAdapter()).code);
        shares = new ERToken();
        ERFeed primary = new ERFeed(5e15); // IMD = $10
        ERFeed nhi = new ERFeed(0.85e18);
        ERFeed spot = new ERFeed(5e15);
        address predicted = vm.computeCreateAddress(address(this), vm.getNonce(address(this)) + 1);
        work = new ERWork(predicted);
        vault = new ParameterizedVault(address(shares), address(0), address(work), address(primary), address(nhi), address(spot));
        assertEq(address(vault), predicted);
        stable = vault.stablecoin();
        shares.mint(BORROWER, 30_000e24);
        vm.prank(BORROWER);
        shares.approve(address(vault), type(uint256).max);
