        vm.prank(BORROWER);
        vault.lock((dollars * 1e18 + PRICE - 1) / PRICE);
    }
    function test_zeroWageMustNotDisableLagForPreviouslyClaimedRights() public {
        _wage(1e18);
        bytes32 root = keccak256(bytes.concat(keccak256(abi.encode(uint256(1), uint32(250), uint64(250)))));
        work.seedRoot(root);
        work.recordRoot();
        vm.prank(BORROWER);
        work.claim(1, 250, 250, new bytes32[](0), root);
        assertEq(work.mintingRights(BORROWER), 250e18);
        _wage(0);
        assertEq(vault.parameters().wage(), 0);
        _lockDollars(2000e18);
        vm.prank(BORROWER);
        vault.draw(1000e18);
        (uint256 lag,) = vault.laggedNow();
        assertEq(lag, 0);
        // Separate top-level calls are separate transactions (the repository's isolate=true).
        // No time elapses between borrowing, earning, repayment and withdrawal.
        vm.prank(BORROWER);
        (bool earned,) = address(vault).call(abi.encodeCall(vault.earn, (250e18)));
        if (!earned) assertEq(vault.totalEarned(), 0);
        vm.prank(BORROWER);
        vault.wipe(1000e18);
        (uint256 collateral,) = vault.positions(BORROWER);
        vm.prank(BORROWER);
        vault.free(collateral);
        assertEq(vault.totalDebt(), 0);
        assertEq(shares.balanceOf(address(vault)), 0);
        assertEq(vault.reserveValue(), 0);
        emit log_named_uint("unbacked work supply", stable.totalSupply());
        // Either earn must refuse while off, or its ceiling must retain the lag.
        assertEq(stable.totalSupply(), 0, "saved rights minted against zero-second debt after wage was switched off");
    }
}

